wikiPage.body:
&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;FAQ officielle&lt;a class=&quot;headeranchor&quot; id=&quot;FAQ_officielle_0&quot; href=&quot;#FAQ_officielle_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq-Officielle.html&quot; title=&quot;FAQ de Paizo&quot;&gt;Page de garde&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs.html&quot; title=&quot;FAQ du Manuel des joueurs&quot;&gt;Manuel des joueurs&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Armes-Et-&#201;quipement.html&quot; title=&quot;FAQ d&amp;#39;Armes et &#233;quipement&quot;&gt;Armes et &#233;quipement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-La-Guerre.html&quot; title=&quot;FAQ de l&amp;#39;Art de la guerre&quot;&gt;l&#39;Art de la guerre&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-La-Magie.html&quot; title=&quot;FAQ de l&amp;#39;Art de la magie&quot;&gt;l&#39;Art de la magie&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-Lintrigue.html&quot; title=&quot;FAQ- de l&amp;#39;Art de l&amp;#39;intrigue&quot;&gt;l&#39;Art de l&#39;intrigue&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Aventures-Occultes.html&quot; title=&quot;FAQ d&amp;#39;Aventures occultes&quot;&gt;Aventures occultes&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Bestiaire.html&quot; title=&quot;FAQ du Bestiaire&quot;&gt;Bestiaire&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Campagnes-Mythiques.html&quot; title=&quot;FAQ de Campagnes mythiques&quot;&gt;Campagnes mythiques&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Guide-De-Campagne.html&quot; title=&quot;FAQ du Guide de campagne&quot;&gt;Guide de campagne&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---Classes-Avanc&#233;es.html&quot; title=&quot;FAQ du Manuel des joueurs - Classes avanc&#233;es&quot;&gt;Manuel des joueurs &lt;br/&gt;- Classes avanc&#233;es&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---R&#232;gles-Avanc&#233;es.html&quot; title=&quot;FAQ du Manuel des joueurs - R&#232;gles avanc&#233;es&quot;&gt;Manuel des joueurs &lt;br/&gt;- R&#232;gles avanc&#233;es&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Races.html&quot; title=&quot;FAQ du Manuel des races&quot;&gt;Manuel des races&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Pathfinder-Unchained.html&quot; title=&quot;FAQ de Pathfinder unchained&quot;&gt;Pathfinder unchained&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;b&gt;&lt;i&gt;Voir la &lt;a class=&quot;externallink&quot; href=&quot;https://paizo.com/paizo/faq/v5748nruor1h8&quot; title=&quot;version originale&quot; target=&quot;_blank&quot;&gt;version originale&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#1&quot; title=&quot;Courtier secret :&quot;&gt;Courtier secret :&lt;/a&gt; Comment le courtier secret est cens&#233; utiliser appel d&#39;ext&#233;rieur sans cercles magiques ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#2&quot; title=&quot;D&#233;fenseur vigilant :&quot;&gt;D&#233;fenseur vigilant :&lt;/a&gt; Quelle est la port&#233;e de jugement partag&#233; ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#3&quot; title=&quot;&#201;tudiant &#233;sot&#233;rique, &#201;clats mystiques :&quot;&gt;&#201;tudiant &#233;sot&#233;rique, &#201;clats mystiques :&lt;/a&gt; Cette capacit&#233; indique qu&#39;elle me permet de la traiter comme une arme l&#233;g&#232;re, mais est-elle manufactur&#233;e ? Les &#233;clats ajoutent-ils mon bonus de Force aux jets de d&#233;g&#226;ts ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#4&quot; title=&quot;Feindre une mal&#233;diction :&quot;&gt;Feindre une mal&#233;diction :&lt;/a&gt; Ce dont devrait-il affecter les cr&#233;atures avec une Intelligence de 2 ou moins ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#5&quot; title=&quot;Fl&#233;chette insaisissable :&quot;&gt;Fl&#233;chette insaisissable :&lt;/a&gt; Dans la description de l&#39;objet, il est indiqu&#233; que 206 po est le prix &#224; l&#39;unit&#233;, mais dans le tableau, il y a un &#171; (50) &#187;. Le prix est-il indiqu&#233; pour un objet ou cinquante ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#6&quot; title=&quot;Justicier :&quot;&gt;Justicier :&lt;/a&gt; Le justicier devrait-il avoir Connaissances (noblesse) comme comp&#233;tence de classe ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#7&quot; title=&quot;Œil mal&#233;fique :&quot;&gt;Œil mal&#233;fique :&lt;/a&gt; Quelles sont les valeurs de Sagesse et de Charisme du familier globe oculaire ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#8&quot; title=&quot;Renomm&#233;e criminelle :&quot;&gt;Renomm&#233;e criminelle :&lt;/a&gt; Ce dont devrait-il avoir un autre avantage au-del&#224; de l&#39;&#233;quivalent de Persuasion pour les criminels ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#9&quot; title=&quot;Tyran :&quot;&gt;Tyran :&lt;/a&gt; Le tyran doit-il vraiment avoir les armes anarchiques comme option pour sa faveur des fi&#233;lons ? Qu&#39;en est-il de &lt;i&gt;cercle magique contre la Loi&lt;/i&gt;, &lt;i&gt;protection contre la Loi partag&#233;e&lt;/i&gt; et &lt;i&gt;rejet de la Loi&lt;/i&gt; ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#10&quot; title=&quot;Voleur fant&#244;me :&quot;&gt;Voleur fant&#244;me :&lt;/a&gt; Le niveau de roublard du voleur fant&#244;me compte-t-il comme son niveau de justicier afin de remplir les conditions des talents sociaux ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;R&#233;ponses&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;ponses_10&quot; href=&quot;#R&#233;ponses_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;1&quot; href=&quot;#1&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Courtier secret : Comment le courtier secret est cens&#233; utiliser appel d&#39;ext&#233;rieur sans cercles magiques ?&lt;a class=&quot;headeranchor&quot; id=&quot;Courtier_secret_:_Comment_le_courtier_secret_est_cens&#233;_utiliser_appel_dext&#233;rieur_sans_cercles_magiques__0&quot; href=&quot;#Courtier_secret_:_Comment_le_courtier_secret_est_cens&#233;_utiliser_appel_dext&#233;rieur_sans_cercles_magiques__0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Courtier-Secret-(Occultiste).html&quot; title=&quot;Courtier secret&quot;&gt;courtier secret&lt;/a&gt;&lt;/u&gt; peut toujours utiliser &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#APPELDEXTERIEUR&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;appel d&#39;ext&#233;rieur&lt;/a&gt;, puisqu&#39;il est incapable de tracer des &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#CERCLESMAGIQUES&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;cercles magiques&lt;/a&gt;, il doit rassembler des secrets sur l&#39;ext&#233;rieur choisi lors d&#39;un rituel qui dure 1 minute (autant qu&#39;il faut &#224; un occultiste pour tracer un cercle magique) et d&#233;penser 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour le faire. Cela sera refl&#233;t&#233; dans le prochain errata.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;2&quot; href=&quot;#2&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;D&#233;fenseur vigilant : Quelle est la port&#233;e de jugement partag&#233; ?&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;fenseur_vigilant_:_Quelle_est_la_port&#233;e_de_jugement_partag&#233;__1&quot; href=&quot;#D&#233;fenseur_vigilant_:_Quelle_est_la_port&#233;e_de_jugement_partag&#233;__1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La port&#233;e est de 18 m&#232;tres. Cela sera refl&#233;t&#233; dans le prochain errata. &lt;i&gt;(Retour &#224; l&#39;&lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Vigilant-(Inquisiteur).html&quot; title=&quot;D&#233;fenseur vigilant&quot;&gt;arch&#233;type&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;3&quot; href=&quot;#3&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;&#201;tudiant &#233;sot&#233;rique, &#201;clats mystiques : Cette capacit&#233; indique qu&#39;elle me permet de la traiter comme une arme l&#233;g&#232;re, mais est-elle manufactur&#233;e ? Les &#233;clats ajoutent-ils mon bonus de Force aux jets de d&#233;g&#226;ts ?&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;tudiant_&#233;sot&#233;rique_&#201;clats_mystiques_:_Cette_capacit&#233;_indique_quelle_me_permet_de_la_traiter_comme_une_arme_l&#233;g&#232;re_mais_est-elle_manufactur&#233;e__Les_&#233;clats_ajoutent-ils_mon_bonus_de_Force_aux_jets_de_d&#233;g&#226;ts__2&quot; href=&quot;#&#201;tudiant_&#233;sot&#233;rique_&#201;clats_mystiques_:_Cette_capacit&#233;_indique_quelle_me_permet_de_la_traiter_comme_une_arme_l&#233;g&#232;re_mais_est-elle_manufactur&#233;e__Les_&#233;clats_ajoutent-ils_mon_bonus_de_Force_aux_jets_de_d&#233;g&#226;ts__2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les &#233;clats mystiques de l&#39;&lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tudiant-&#201;sot&#233;rique-(Justicier).html&quot; title=&quot;&#201;tudiant &#233;sot&#233;rique&quot;&gt;&#233;tudiant &#233;sot&#233;rique&lt;/a&gt;&lt;/u&gt; ne sont pas des armes manufactur&#233;es, il s&#39;agit d&#39;effets magiques (similaires &#224; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rayon-Ardent.html&quot; title=&quot;Rayon ardent&quot;&gt;rayon ardent&lt;/a&gt;&lt;/i&gt; ou les flammes produites par &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flammes.html&quot; title=&quot;Flammes&quot;&gt;flammes&lt;/a&gt;&lt;/i&gt;), et le personnage n&#39;ajoute pas son bonus de Force &#224; leurs &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;4&quot; href=&quot;#4&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Feindre une mal&#233;diction : Ce dont devrait-il affecter les cr&#233;atures avec une Intelligence de 2 ou moins ?&lt;a class=&quot;headeranchor&quot; id=&quot;Feindre_une_mal&#233;diction_:_Ce_dont_devrait-il_affecter_les_cr&#233;atures_avec_une_Intelligence_de_C_ou_moins__3&quot; href=&quot;#Feindre_une_mal&#233;diction_:_Ce_dont_devrait-il_affecter_les_cr&#233;atures_avec_une_Intelligence_de_C_ou_moins__3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Non, de telles cr&#233;atures ne devraient pas &#234;tre affect&#233;es. Cela sera refl&#233;t&#233; dans le prochain errata. &lt;i&gt;(Retour au &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Feindre-Une-Mal&#233;diction.html&quot; title=&quot;Feindre une mal&#233;diction&quot;&gt;don&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;5&quot; href=&quot;#5&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Fl&#233;chette insaisissable : Dans la description de l&#39;objet, il est indiqu&#233; que 206 po est le prix &#224; l&#39;unit&#233;, mais dans le tableau, il y a un &#171; (50) &#187;. Le prix est-il indiqu&#233; pour un objet ou cinquante ?&lt;a class=&quot;headeranchor&quot; id=&quot;Fl&#233;chette_insaisissable_:_Dans_la_description_de_lobjet_il_est_indiqu&#233;_que_CAG_po_est_le_prix_&#224;_lunit&#233;_mais_dans_le_tableau_il_y_a_un_&#171;_FA_&#187;_Le_prix_est-il_indiqu&#233;_pour_un_objet_ou_cinquante__4&quot; href=&quot;#Fl&#233;chette_insaisissable_:_Dans_la_description_de_lobjet_il_est_indiqu&#233;_que_CAG_po_est_le_prix_&#224;_lunit&#233;_mais_dans_le_tableau_il_y_a_un_&#171;_FA_&#187;_Le_prix_est-il_indiqu&#233;_pour_un_objet_ou_cinquante__4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;chette-Insaisissable.html&quot; title=&quot;Fl&#233;chette insaisissable&quot;&gt;description&lt;/a&gt;&lt;/u&gt; est correcte, le &#171; (50) &#187; ne devrait pas &#234;tre pr&#233;sent dans le tableau. Cela sera refl&#233;t&#233; dans le prochain errata.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;6&quot; href=&quot;#6&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Justicier : Le justicier devrait-il avoir Connaissances (noblesse) comme comp&#233;tence de classe ?&lt;a class=&quot;headeranchor&quot; id=&quot;Justicier_:_Le_justicier_devrait-il_avoir_Connaissances_noblesse_comme_comp&#233;tence_de_classe__5&quot; href=&quot;#Justicier_:_Le_justicier_devrait-il_avoir_Connaissances_noblesse_comme_comp&#233;tence_de_classe__5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Oui, il devrait. Cela sera refl&#233;t&#233; dans le prochain errata. &lt;i&gt;(Retour &#224; la &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Justicier.html&quot; title=&quot;Le justicier&quot;&gt;classe&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;7&quot; href=&quot;#7&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Œil mal&#233;fique : Quelles sont les valeurs de Sagesse et de Charisme du familier globe oculaire ?&lt;a class=&quot;headeranchor&quot; id=&quot;Œil_mal&#233;fique_:_Quelles_sont_les_valeurs_de_Sagesse_et_de_Charisme_du_familier_globe_oculaire__6&quot; href=&quot;#Œil_mal&#233;fique_:_Quelles_sont_les_valeurs_de_Sagesse_et_de_Charisme_du_familier_globe_oculaire__6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les deux ont une valeur de 10. &lt;i&gt;(Retour &#224; l&#39;&lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Œil-Mal&#233;fique-(Hypnotiseur).html&quot; title=&quot;Œil mal&#233;fique&quot;&gt;arch&#233;type&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;8&quot; href=&quot;#8&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Renomm&#233;e criminelle : Ce dont devrait-il avoir un autre avantage au-del&#224; de l&#39;&#233;quivalent de Persuasion pour les criminels ?&lt;a class=&quot;headeranchor&quot; id=&quot;Renomm&#233;e_criminelle_:_Ce_dont_devrait-il_avoir_un_autre_avantage_au-del&#224;_de_l&#233;quivalent_de_Persuasion_pour_les_criminels__7&quot; href=&quot;#Renomm&#233;e_criminelle_:_Ce_dont_devrait-il_avoir_un_autre_avantage_au-del&#224;_de_l&#233;quivalent_de_Persuasion_pour_les_criminels__7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Oui, les personnages avec &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Renomm&#233;e-Criminelle.html&quot; title=&quot;Renomm&#233;e criminelle&quot;&gt;Renomm&#233;e criminelle&lt;/a&gt;&lt;/u&gt; obtiennent le bonus de +2 (ou +4 s&#39;ils poss&#232;dent 10 rangs ou plus) aux &lt;a class=&quot;pagelink&quot; href=&quot;Influence-Individuelle.html#Les_tests_dinfluence_2&quot; title=&quot;L&amp;#39;influence individuelle&quot;&gt;tests d&#39;influence&lt;/a&gt; sur les criminels, m&#234;me si la comp&#233;tence associ&#233;e n&#39;est ni &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; ni &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;. Ils ont &#233;galement besoin de 1 influence de moins par rang pour atteindre un nouveau &lt;a class=&quot;pagelink&quot; href=&quot;Influence-Organisationnelle.html#Points_et_rangs_dinfluence_7&quot; title=&quot;L&amp;#39;influence organisationnelle&quot;&gt;rang d&#39;influence&lt;/a&gt; avec une organisation criminelle (qu&#39;il soit positif ou n&#233;gatif).&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;9&quot; href=&quot;#9&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Tyran : Le tyran doit-il vraiment avoir les armes anarchiques comme option pour sa faveur des fi&#233;lons ? Qu&#39;en est-il de &lt;i&gt;cercle magique contre la Loi&lt;/i&gt;, &lt;i&gt;protection contre la Loi partag&#233;e&lt;/i&gt; et &lt;i&gt;rejet de la Loi&lt;/i&gt; ?&lt;a class=&quot;headeranchor&quot; id=&quot;Tyran_:_Le_tyran_doit-il_vraiment_avoir_les_armes_anarchiques_comme_option_pour_sa_faveur_des_fi&#233;lons__Quen_est-il_de_cercle_magique_contre_la_Loi__protection_contre_la_Loi_partag&#233;e_et_rejet_de_la_Loi__8&quot; href=&quot;#Tyran_:_Le_tyran_doit-il_vraiment_avoir_les_armes_anarchiques_comme_option_pour_sa_faveur_des_fi&#233;lons__Quen_est-il_de_cercle_magique_contre_la_Loi__protection_contre_la_Loi_partag&#233;e_et_rejet_de_la_Loi__8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Non, le &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-(Antipaladin).html&quot; title=&quot;Tyran&quot;&gt;tyran&lt;/a&gt;&lt;/u&gt; devrait avoir les armes &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Axiomatique.html&quot; title=&quot;axiomatique (propri&#233;t&#233;)&quot;&gt;axiomatiques&lt;/a&gt;&lt;/i&gt; dans le cadre de sa &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#FAVEURDESFIELONS&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;faveur des fi&#233;lons&lt;/a&gt;, et les sorts devraient tous &#234;tre contre le Chaos, et non pas la Loi. Cela sera refl&#233;t&#233; dans le prochain errata.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;10&quot; href=&quot;#10&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Voleur fant&#244;me : Le niveau de roublard du voleur fant&#244;me compte-t-il comme son niveau de justicier afin de remplir les conditions des talents sociaux ?&lt;a class=&quot;headeranchor&quot; id=&quot;Voleur_fant&#244;me_:_Le_niveau_de_roublard_du_voleur_fant&#244;me_compte-t-il_comme_son_niveau_de_justicier_afin_de_remplir_les_conditions_des_talents_sociaux__9&quot; href=&quot;#Voleur_fant&#244;me_:_Le_niveau_de_roublard_du_voleur_fant&#244;me_compte-t-il_comme_son_niveau_de_justicier_afin_de_remplir_les_conditions_des_talents_sociaux__9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Oui.  &lt;i&gt;(Retour &#224; l&#39;&lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Voleur-Fant&#244;me-(Roublard).html&quot; title=&quot;Voleur fant&#244;me&quot;&gt;arch&#233;type&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;
